44:  * @param <T> The type of the input elements and the feedback elements.
45:  */
46: @Internal
47: public class FeedbackTransformation<T> extends Transformation<T> {
48: 
49:     private final Transformation<T> input;
50: 
51:     private final List<Transformation<T>> feedbackEdges;
52: 
53:     private final Long waitTime;
54: 
55:     /**
56:      * Creates a new {@code FeedbackTransformation} from the given input.
57:      *
58:      * @param input The input {@code Transformation}
59:      * @param waitTime The wait time of the feedback operator. After the time expires the operation
60:      *     will close and not receive any more feedback elements.
61:      */
62:     public FeedbackTransformation(Transformation<T> input, Long waitTime) {
63:         super("Feedback", input.getOutputType(), input.getParallelism(), false);
64:         this.input = input;
65:         this.waitTime = waitTime;
66:         this.feedbackEdges = Lists.newArrayList();
67:     }
