405:         DataStream<Long> keyed = source2.keyBy(r -> 0L);
406: 
407:         final MapStateDescriptor<Long, Long> descriptor =
408:                 new MapStateDescriptor<>(
409:                         "broadcast", BasicTypeInfo.LONG_TYPE_INFO, BasicTypeInfo.LONG_TYPE_INFO);
410:         final BroadcastStream<Long> broadcast = map1.broadcast(descriptor);
411:         final SingleOutputStreamOperator<Long> joined =
412:                 keyed.connect(broadcast)
413:                         .process(
414:                                 new KeyedBroadcastProcessFunction<Long, Long, Long, Long>() {
415:                                     @Override
416:                                     public void processElement(
417:                                             Long value, ReadOnlyContext ctx, Collector<Long> out) {}
418: 
419:                                     @Override
420:                                     public void processBroadcastElement(
421:                                             Long value, Context ctx, Collector<Long> out) {}
422:                                 });
423: 
424:         StreamGraph streamGraph = env.getStreamGraph();
425:         assertThat(streamGraph.getStreamNodes().size()).isEqualTo(4);
426: 
427:         // single broadcast
428:         assertThat(edge(streamGraph, source1, map1))
429:                 .is(matching(supportsUnalignedCheckpoints(false)));
430:         // keyed, connected with broadcast
431:         assertThat(edge(streamGraph, source2, joined))
432:                 .is(matching(supportsUnalignedCheckpoints(false)));
433:         // broadcast, connected with keyed
434:         assertThat(edge(streamGraph, map1, joined))
435:                 .is(matching(supportsUnalignedCheckpoints(false)));
436:     }
