438:     private static StreamEdge edge(
439:             StreamGraph streamGraph, DataStream<Long> op1, DataStream<Long> op2) {
440:         List<StreamEdge> streamEdges = streamGraph.getStreamEdges(op1.getId(), op2.getId());
441:         assertThat(streamEdges).hasSize(1);
442:         return streamEdges.get(0);
443:     }
