445:     private static Matcher<StreamEdge> supportsUnalignedCheckpoints(boolean enabled) {
446:         return new FeatureMatcher<StreamEdge, Boolean>(
447:                 equalTo(enabled),
448:                 "supports unaligned checkpoint",
449:                 "supports unaligned checkpoint") {
450:             @Override
451:             protected Boolean featureValueOf(StreamEdge actual) {
452:                 return actual.supportsUnalignedCheckpoints();
453:             }
454:         };
455:     }
