69:     public JarRunHandler(
70:             final GatewayRetriever<? extends DispatcherGateway> leaderRetriever,
71:             final Time timeout,
72:             final Map<String, String> responseHeaders,
73:             final MessageHeaders<JarRunRequestBody, JarRunResponseBody, JarRunMessageParameters>
74:                     messageHeaders,
75:             final Path jarDir,
76:             final Configuration configuration,
77:             final Executor executor,
78:             final Supplier<ApplicationRunner> applicationRunnerSupplier) {
79:         super(leaderRetriever, timeout, responseHeaders, messageHeaders);
80: 
81:         this.jarDir = requireNonNull(jarDir);
82:         this.configuration = requireNonNull(configuration);
83:         this.executor = requireNonNull(executor);
84: 
85:         this.applicationRunner = applicationRunnerSupplier.get();
86:     }
