88:     @Override
89:     @VisibleForTesting
90:     public CompletableFuture<JarRunResponseBody> handleRequest(
91:             @Nonnull final HandlerRequest<JarRunRequestBody> request,
92:             @Nonnull final DispatcherGateway gateway)
93:             throws RestHandlerException {
94: 
95:         final Configuration effectiveConfiguration = new Configuration(configuration);
96:         effectiveConfiguration.set(DeploymentOptions.ATTACHED, false);
97:         effectiveConfiguration.set(DeploymentOptions.TARGET, EmbeddedExecutor.NAME);
98: 
99:         final JarHandlerContext context = JarHandlerContext.fromRequest(request, jarDir, log);
100:         context.applyToConfiguration(effectiveConfiguration, request);
101:         SavepointRestoreSettings.toConfiguration(
102:                 getSavepointRestoreSettings(request, effectiveConfiguration),
103:                 effectiveConfiguration);
104: 
105:         final PackagedProgram program = context.toPackagedProgram(effectiveConfiguration);
106: 
107:         return CompletableFuture.supplyAsync(
108:                         () -> applicationRunner.run(gateway, program, effectiveConfiguration),
109:                         executor)
110:                 .handle(
111:                         (jobIds, throwable) -> {
112:                             program.close();
113:                             if (throwable != null) {
114:                                 throw new CompletionException(
115:                                         new RestHandlerException(
116:                                                 "Could not execute application.",
117:                                                 HttpResponseStatus.BAD_REQUEST,
118:                                                 throwable));
119:                             } else if (jobIds.isEmpty()) {
120:                                 throw new CompletionException(
121:                                         new RestHandlerException(
122:                                                 "No jobs included in application.",
123:                                                 HttpResponseStatus.BAD_REQUEST));
124:                             }
125:                             return new JarRunResponseBody(jobIds.get(0));
126:                         });
127:     }
