129:     private SavepointRestoreSettings getSavepointRestoreSettings(
130:             final @Nonnull HandlerRequest<JarRunRequestBody> request,
131:             final Configuration effectiveConfiguration)
132:             throws RestHandlerException {
133: 
134:         final JarRunRequestBody requestBody = request.getRequestBody();
135: 
136:         final boolean allowNonRestoredState =
137:                 fromRequestBodyOrQueryParameter(
138:                         requestBody.getAllowNonRestoredState(),
139:                         () -> getQueryParameter(request, AllowNonRestoredStateQueryParameter.class),
140:                         effectiveConfiguration.get(
141:                                 StateRecoveryOptions.SAVEPOINT_IGNORE_UNCLAIMED_STATE),
142:                         log);
143:         final String savepointPath =
144:                 fromRequestBodyOrQueryParameter(
145:                         emptyToNull(requestBody.getSavepointPath()),
146:                         () ->
147:                                 emptyToNull(
148:                                         getQueryParameter(
149:                                                 request, SavepointPathQueryParameter.class)),
150:                         effectiveConfiguration.get(StateRecoveryOptions.SAVEPOINT_PATH),
151:                         log);
152:         final RecoveryClaimMode claimMode =
153:                 Optional.ofNullable(requestBody.getRestoreMode())
154:                         .orElseGet(
155:                                 () ->
156:                                         effectiveConfiguration.get(
157:                                                 StateRecoveryOptions.RESTORE_MODE));
158:         if (requestBody.isDeprecatedRestoreModeHasValue()) {
159:             log.warn("The option 'restoreMode' is deprecated, please use 'claimMode' instead.");
160:         }
161:         if (claimMode.equals(RecoveryClaimMode.LEGACY)) {
162:             log.warn(
163:                     "The {} restore mode is deprecated, please use {} or {} mode instead.",
164:                     RecoveryClaimMode.LEGACY,
165:                     RecoveryClaimMode.CLAIM,
166:                     RecoveryClaimMode.NO_CLAIM);
167:         }
168:         final SavepointRestoreSettings savepointRestoreSettings;
169:         if (savepointPath != null) {
170:             savepointRestoreSettings =
171:                     SavepointRestoreSettings.forPath(
172:                             savepointPath, allowNonRestoredState, claimMode);
173:         } else {
174:             savepointRestoreSettings = SavepointRestoreSettings.none();
175:         }
176:         return savepointRestoreSettings;
177:     }
