448:     private void testRestartVerticesOnFailuresInScheduling(
449:             Consumer<ExecutionVertexID> actionsToTriggerTaskFailure) throws Exception {
450:         final int parallelism = 2;
451:         final JobVertex v1 = createVertex("vertex1", parallelism);
452:         final JobVertex v2 = createVertex("vertex2", parallelism);
453:         v2.connectNewDataSetAsInput(
454:                 v1, DistributionPattern.POINTWISE, ResultPartitionType.PIPELINED);
455: 
456:         final JobGraph jobGraph = JobGraphTestUtils.streamingJobGraph(v1, v2);
457: 
458:         testExecutionSlotAllocator.disableAutoCompletePendingRequests();
459:         final TestSchedulingStrategy.Factory schedulingStrategyFactory =
460:                 new TestSchedulingStrategy.Factory();
461:         final DefaultScheduler scheduler =
462:                 createScheduler(
463:                         jobGraph,
464:                         ComponentMainThreadExecutorServiceAdapter.forMainThread(),
465:                         schedulingStrategyFactory,
466:                         new RestartPipelinedRegionFailoverStrategy.Factory());
467:         final TestSchedulingStrategy schedulingStrategy =
468:                 schedulingStrategyFactory.getLastCreatedSchedulingStrategy();
469:         scheduler.startScheduling();
470: 
471:         final ExecutionVertexID vid11 = new ExecutionVertexID(v1.getID(), 0);
472:         final ExecutionVertexID vid12 = new ExecutionVertexID(v1.getID(), 1);
473:         final ExecutionVertexID vid21 = new ExecutionVertexID(v2.getID(), 0);
474:         final ExecutionVertexID vid22 = new ExecutionVertexID(v2.getID(), 1);
475:         schedulingStrategy.schedule(Arrays.asList(vid11, vid12, vid21, vid22));
476: 
477:         assertThat(testExecutionSlotAllocator.getPendingRequests()).hasSize(4);
478: 
479:         actionsToTriggerTaskFailure.accept(vid11);
480: 
481:         final Iterator<ArchivedExecutionVertex> vertexIterator =
482:                 scheduler
483:                         .requestJob()
484:                         .getArchivedExecutionGraph()
485:                         .getAllExecutionVertices()
486:                         .iterator();
487:         final ArchivedExecutionVertex ev11 = vertexIterator.next();
488:         final ArchivedExecutionVertex ev12 = vertexIterator.next();
489:         final ArchivedExecutionVertex ev21 = vertexIterator.next();
490:         final ArchivedExecutionVertex ev22 = vertexIterator.next();
491: 
492:         // ev11 and ev21 needs to be restarted because it is pipelined region failover and
493:         // they are in the same region. ev12 and ev22 will not be affected
494:         assertThat(testExecutionSlotAllocator.getPendingRequests()).hasSize(2);
495:         assertThat(ev11.getExecutionState()).isEqualTo(ExecutionState.FAILED);
496:         assertThat(ev21.getExecutionState()).isEqualTo(ExecutionState.CANCELED);
497:         assertThat(ev12.getExecutionState()).isEqualTo(ExecutionState.SCHEDULED);
498:         assertThat(ev22.getExecutionState()).isEqualTo(ExecutionState.SCHEDULED);
499: 
500:         taskRestartExecutor.triggerScheduledTasks();
501:         assertThat(schedulingStrategy.getReceivedVerticesToRestart()).contains(vid11, vid21);
502:     }
