675:     /**
676:      * This test covers the use-case where a global fail-over is followed by a local task failure.
677:      * It verifies (besides checking the expected deployments) that the assert in the global
678:      * recovery handling of {@link SchedulerBase#restoreState} is not triggered due to version
679:      * updates.
680:      */
681:     @Test
682:     void handleGlobalFailureWithLocalFailure() {
683:         final JobGraph jobGraph = singleJobVertexJobGraph(2);
684:         final JobVertex onlyJobVertex = getOnlyJobVertex(jobGraph);
685:         enableCheckpointing(jobGraph);
686: 
687:         final DefaultScheduler scheduler = createSchedulerAndStartScheduling(jobGraph);
688: 
689:         final List<ExecutionAttemptID> attemptIds =
690:                 StreamSupport.stream(
691:                                 scheduler
692:                                         .requestJob()
693:                                         .getArchivedExecutionGraph()
694:                                         .getAllExecutionVertices()
695:                                         .spliterator(),
696:                                 false)
697:                         .map(ArchivedExecutionVertex::getCurrentExecutionAttempt)
698:                         .map(ArchivedExecution::getAttemptId)
699:                         .collect(Collectors.toList());
700:         final ExecutionAttemptID localFailureAttemptId = attemptIds.get(0);
701:         scheduler.handleGlobalFailure(new Exception("global failure"));
702:         // the local failure shouldn't affect the global fail-over
703:         scheduler.updateTaskExecutionState(
704:                 new TaskExecutionState(
705:                         localFailureAttemptId,
706:                         ExecutionState.FAILED,
707:                         new Exception("local failure")));
708: 
709:         for (ExecutionAttemptID attemptId : attemptIds) {
710:             scheduler.updateTaskExecutionState(
711:                     new TaskExecutionState(attemptId, ExecutionState.CANCELED));
712:         }
713: 
714:         taskRestartExecutor.triggerScheduledTasks();
715: 
716:         final ExecutionVertexID executionVertexId0 =
717:                 new ExecutionVertexID(onlyJobVertex.getID(), 0);
718:         final ExecutionVertexID executionVertexId1 =
719:                 new ExecutionVertexID(onlyJobVertex.getID(), 1);
720:         assertThat(testExecutionOperations.getDeployedVertices())
721:                 .withFailMessage(
722:                         "The "
723:                                 + "execution vertices should be deployed in a specific order reflecting the "
724:                                 + "scheduling start and the global fail-over afterwards.")
725:                 .contains(
726:                         executionVertexId0,
727:                         executionVertexId1,
728:                         executionVertexId0,
729:                         executionVertexId1);
730:     }
