1183:     @Test
1184:     void pendingSlotRequestsOfVerticesToRestartWillNotBeFulfilledByReturnedSlots()
1185:             throws Exception {
1186:         final int parallelism = 10;
1187:         final JobGraph jobGraph = sourceSinkJobGraph(parallelism);
1188:         testExecutionSlotAllocator.disableAutoCompletePendingRequests();
1189:         testExecutionSlotAllocator.enableCompletePendingRequestsWithReturnedSlots();
1190: 
1191:         final DefaultScheduler scheduler =
1192:                 createScheduler(
1193:                         jobGraph,
1194:                         ComponentMainThreadExecutorServiceAdapter.forMainThread(),
1195:                         new PipelinedRegionSchedulingStrategy.Factory(),
1196:                         new RestartAllFailoverStrategy.Factory());
1197:         scheduler.startScheduling();
1198: 
1199:         final ExecutionVertex ev1 =
1200:                 Iterables.get(scheduler.getExecutionGraph().getAllExecutionVertices(), 0);
1201: 
1202:         final Set<CompletableFuture<LogicalSlot>> pendingLogicalSlotFutures =
1203:                 testExecutionSlotAllocator.getPendingRequests().values().stream()
1204:                         .map(ExecutionSlotAssignment::getLogicalSlotFuture)
1205:                         .collect(Collectors.toSet());
1206:         assertThat(pendingLogicalSlotFutures).hasSize(parallelism * 2);
1207: 
1208:         testExecutionSlotAllocator.completePendingRequest(ev1.getID());
1209:         assertThat(pendingLogicalSlotFutures.stream().filter(CompletableFuture::isDone).count())
1210:                 .isEqualTo(1L);
1211: 
1212:         final String exceptionMessage = "expected exception";
1213:         scheduler.updateTaskExecutionState(
1214:                 new TaskExecutionState(
1215:                         ev1.getCurrentExecutionAttempt().getAttemptId(),
1216:                         ExecutionState.FAILED,
1217:                         new RuntimeException(exceptionMessage)));
1218: 
1219:         assertThat(testExecutionSlotAllocator.getPendingRequests()).isEmpty();
1220: 
1221:         // the failed task will return its slot before triggering failover. And the slot
1222:         // will be returned and re-assigned to another task which is waiting for a slot.
1223:         // failover will be triggered after that and the re-assigned slot will be returned
1224:         // once the attached task is canceled, but the slot will not be assigned to other
1225:         // tasks which are identified to be restarted soon.
1226:         assertThat(testExecutionSlotAllocator.getReturnedSlots()).hasSize(2);
1227:         assertThat(
1228:                         pendingLogicalSlotFutures.stream()
1229:                                 .filter(CompletableFuture::isCancelled)
1230:                                 .count())
1231:                 .isEqualTo(parallelism * 2L - 2L);
1232:     }
