1928:     public static void doTestCheckpointCleanerIsClosedAfterCheckpointServices(
1929:             BiFunction<CheckpointRecoveryFactory, CheckpointsCleaner, SchedulerNG> schedulerFactory,
1930:             ScheduledExecutorService executorService,
1931:             Logger logger)
1932:             throws Exception {
1933:         final CountDownLatch checkpointServicesShutdownBlocked = new CountDownLatch(1);
1934:         final CountDownLatch cleanerClosed = new CountDownLatch(1);
1935:         final CompletedCheckpointStore completedCheckpointStore =
1936:                 new StandaloneCompletedCheckpointStore(1) {
1937: 
1938:                     @Override
1939:                     public void shutdown(JobStatus jobStatus, CheckpointsCleaner checkpointsCleaner)
1940:                             throws Exception {
1941:                         checkpointServicesShutdownBlocked.await();
1942:                         super.shutdown(jobStatus, checkpointsCleaner);
1943:                     }
1944:                 };
1945:         final CheckpointIDCounter checkpointIDCounter =
1946:                 new StandaloneCheckpointIDCounter() {
1947: 
1948:                     @Override
1949:                     public CompletableFuture<Void> shutdown(JobStatus jobStatus) {
1950:                         try {
