300:     /**
301:      * Test for SyncSavepoint and EndInput interactions. Targets following scenarios scenarios:
302:      *
303:      * <ol>
304:      *   <li>Thread1: notify sync savepoint
305:      *   <li>Thread2: endInput
306:      *   <li>Thread1: confirm/abort/abortAsync
307:      *   <li>assert inputEnded: confirmed - no, abort/abortAsync - yes
308:      * </ol>
309:      */
310:     private void testSyncSavepointWithEndInput(
311:             BiConsumerWithException<StreamTask<?, ?>, Long, IOException> savepointResult,
312:             SnapshotType checkpointType,
313:             boolean expectEndInput)
314:             throws Exception {
315:         StreamTaskMailboxTestHarness<String> harness =
316:                 new StreamTaskMailboxTestHarnessBuilder<>(OneInputStreamTask::new, STRING_TYPE_INFO)
317:                         .addInput(STRING_TYPE_INFO)
318:                         .setupOutputForSingletonOperatorChain(
319:                                 new TestBoundedOneInputStreamOperator())
320:                         .build();
321: 
322:         final long checkpointId = 1L;
323:         CountDownLatch savepointTriggeredLatch = new CountDownLatch(1);
324:         CountDownLatch inputEndedLatch = new CountDownLatch(1);
325: 
326:         MailboxExecutor executor =
327:                 harness.streamTask.getMailboxExecutorFactory().createExecutor(MAX_PRIORITY);
328:         executor.execute(
329:                 () -> {
330:                     try {
331:                         harness.streamTask.triggerCheckpointOnBarrier(
332:                                 new CheckpointMetaData(checkpointId, checkpointId),
333:                                 new CheckpointOptions(checkpointType, getDefault()),
334:                                 new CheckpointMetricsBuilder());
335:                     } catch (IOException e) {
336:                         fail(e.getMessage());
337:                     }
338:                 },
339:                 "triggerCheckpointOnBarrier");
340:         new Thread(
341:                         () -> {
342:                             try {
343:                                 savepointTriggeredLatch.await();
344:                                 harness.endInput(expectEndInput);
345:                                 inputEndedLatch.countDown();
346:                             } catch (InterruptedException e) {
347:                                 fail(e.getMessage());
348:                             }
349:                         })
350:                 .start();
351:         // this mails should be executed from the one above (from triggerCheckpointOnBarrier)
352:         executor.execute(savepointTriggeredLatch::countDown, "savepointTriggeredLatch");
353:         executor.execute(
354:                 () -> {
355:                     inputEndedLatch.await();
356:                     savepointResult.accept(harness.streamTask, checkpointId);
357:                 },
358:                 "savepointResult");
359:         harness.processAll();
360: 
361:         assertThat(TestBoundedOneInputStreamOperator.isInputEnded()).isEqualTo(expectEndInput);
362:     }
