768:     /**
769:      * FLINK-5667
770:      *
771:      * <p>Tests that a concurrent cancel operation does not discard the state handles of an
772:      * acknowledged checkpoint. The situation can only happen if the cancel call is executed after
773:      * Environment.acknowledgeCheckpoint() and before the CloseableRegistry.unregisterClosable()
774:      * call.
775:      */
776:     @Test
777:     void testAsyncCheckpointingConcurrentCloseAfterAcknowledge() throws Exception {
778: 
779:         final OneShotLatch acknowledgeCheckpointLatch = new OneShotLatch();
780:         final OneShotLatch completeAcknowledge = new OneShotLatch();
781: 
782:         CheckpointResponder checkpointResponder = mock(CheckpointResponder.class);
783:         doAnswer(
784:                         new Answer() {
785:                             @Override
786:                             public Object answer(InvocationOnMock invocation) {
787:                                 acknowledgeCheckpointLatch.trigger();
788: 
789:                                 // block here so that we can issue the concurrent cancel call
790:                                 while (true) {
791:                                     try {
792:                                         // wait until we successfully await (no pun intended)
