1687:         final ThroughputCalculator throughputCalculator =
1688:                 new ThroughputCalculator(SystemClock.getInstance() /* parameters are ignored */) {
1689:                     private int callCount = 0;
1690: 
1691:                     @Override
1692:                     public long calculateThroughput() {
1693:                         if (callCount++ % 2 == 0) {
