1958:     private static class RunningTask<T extends StreamTask<?, ?>> {
1959:         final T streamTask;
1960:         final CompletableFuture<Void> invocationFuture;
1961: 
1962:         RunningTask(T streamTask, CompletableFuture<Void> invocationFuture) {
1963:             this.streamTask = streamTask;
1964:             this.invocationFuture = invocationFuture;
1965:         }
1966: 
1967:         void waitForTaskCompletion(boolean cancelled) throws Exception {
1968:             try {
1969:                 invocationFuture.get();
1970:             } catch (Exception e) {
1971:                 if (cancelled) {
1972:                     assertThat(e).hasCauseInstanceOf(CancelTaskException.class);
