1981:     private static <T extends StreamTask<?, ?>> RunningTask<T> runTask(
1982:             SupplierWithException<T, Exception> taskFactory) throws Exception {
1983:         CompletableFuture<T> taskCreationFuture = new CompletableFuture<>();
1984:         CompletableFuture<Void> invocationFuture =
1985:                 CompletableFuture.runAsync(
1986:                         () -> {
1987:                             T task;
1988:                             try {
1989:                                 task = taskFactory.get();
1990:                                 taskCreationFuture.complete(task);
1991:                             } catch (Exception e) {
1992:                                 taskCreationFuture.completeExceptionally(e);
1993:                                 return;
1994:                             }
1995:                             try {
1996:                                 task.invoke();
1997:                             } catch (RuntimeException e) {
1998:                                 throw e;
1999:                             } catch (Exception e) {
2000:                                 throw new RuntimeException(e);
2001:                             }
2002:                         },
2003:                         Executors.newSingleThreadExecutor());
2004: 
2005:         // Wait until task is created.
2006:         return new RunningTask<>(taskCreationFuture.get(), invocationFuture);
2007:     }
