2615:     private static final class BlockingRunnableFuture<V> implements RunnableFuture<V> {
2616: 
2617:         private final CompletableFuture<V> future = new CompletableFuture<>();
2618: 
2619:         private final OneShotLatch signalRunLatch = new OneShotLatch();
2620: 
2621:         private final CountDownLatch continueRunLatch;
2622: 
2623:         private final V value;
2624: 
2625:         private BlockingRunnableFuture(int parties, V value) {
2626:             this.continueRunLatch = new CountDownLatch(parties);
2627:             this.value = value;
2628:         }
2629: 
2630:         @Override
2631:         public void run() {
2632:             signalRunLatch.trigger();
2633:             continueRunLatch.countDown();
2634: 
2635:             try {
2636:                 // poor man's barrier because it can happen that the async operations thread gets
2637:                 // interrupted by the mail box thread. The CyclicBarrier would in this case fail
2638:                 // all participants of the barrier, leaving the future uncompleted
2639:                 continueRunLatch.await();
2640:             } catch (InterruptedException e) {
2641:                 ExceptionUtils.rethrow(e);
2642:             }
2643: 
2644:             future.complete(value);
2645:         }
2646: 
2647:         @Override
2648:         public boolean cancel(boolean mayInterruptIfRunning) {
2649:             return false;
2650:         }
2651: 
2652:         @Override
2653:         public boolean isCancelled() {
2654:             return future.isCancelled();
2655:         }
2656: 
2657:         @Override
2658:         public boolean isDone() {
2659:             return future.isDone();
2660:         }
2661: 
2662:         @Override
2663:         public V get() throws InterruptedException, ExecutionException {
2664:             return future.get();
2665:         }
2666: 
2667:         @Override
2668:         public V get(long timeout, TimeUnit unit)
2669:                 throws InterruptedException, ExecutionException, TimeoutException {
2670:             return future.get(timeout, unit);
2671:         }
2672: 
2673:         void awaitRun() throws InterruptedException {
2674:             signalRunLatch.await();
2675:         }
2676:     }
