237:     /**
238:      * Private constructor that creates a re-configured copy of the state backend.
239:      *
240:      * @param original The state backend to re-configure.
241:      * @param config The configuration.
242:      * @param classLoader The class loader.
243:      */
244:     private EmbeddedRocksDBStateBackend(
245:             EmbeddedRocksDBStateBackend original, ReadableConfig config, ClassLoader classLoader) {
246:         // configure incremental checkpoints
247:         this.enableIncrementalCheckpointing =
248:                 original.enableIncrementalCheckpointing.resolveUndefined(
249:                         config.get(CheckpointingOptions.INCREMENTAL_CHECKPOINTS));
250: 
251:         if (original.numberOfTransferThreads == UNDEFINED_NUMBER_OF_TRANSFER_THREADS) {
252:             this.numberOfTransferThreads = config.get(CHECKPOINT_TRANSFER_THREAD_NUM);
253:         } else {
254:             this.numberOfTransferThreads = original.numberOfTransferThreads;
255:         }
256: 
257:         if (original.writeBatchSize == UNDEFINED_WRITE_BATCH_SIZE) {
258:             this.writeBatchSize = config.get(WRITE_BATCH_SIZE).getBytes();
259:         } else {
260:             this.writeBatchSize = original.writeBatchSize;
261:         }
262: 
263:         this.memoryConfiguration =
264:                 RocksDBMemoryConfiguration.fromOtherAndConfiguration(
265:                         original.memoryConfiguration, config);
266:         this.memoryConfiguration.validate();
267: 
268:         this.priorityQueueConfig =
269:                 RocksDBPriorityQueueConfig.fromOtherAndConfiguration(
270:                         original.priorityQueueConfig, config);
271: 
272:         // configure local directories
273:         if (original.localRocksDbDirectories != null) {
274:             this.localRocksDbDirectories = original.localRocksDbDirectories;
275:         } else {
276:             final String rocksdbLocalPaths = config.get(RocksDBOptions.LOCAL_DIRECTORIES);
277:             if (rocksdbLocalPaths != null) {
278:                 String[] directories = rocksdbLocalPaths.split(",|" + File.pathSeparator);
279: 
280:                 try {
281:                     setDbStoragePaths(directories);
282:                 } catch (IllegalArgumentException e) {
283:                     throw new IllegalConfigurationException(
284:                             "Invalid configuration for RocksDB state "
285:                                     + "backend's local storage directories: "
286:                                     + e.getMessage(),
287:                             e);
288:                 }
289:             }
290:         }
291: 
292:         // configure metric options
293:         this.nativeMetricOptions = RocksDBNativeMetricOptions.fromConfig(config);
294: 
295:         // configure RocksDB predefined options
296:         this.predefinedOptions =
297:                 original.predefinedOptions == null
298:                         ? PredefinedOptions.valueOf(config.get(RocksDBOptions.PREDEFINED_OPTIONS))
299:                         : original.predefinedOptions;
300:         LOG.info("Using predefined options: {}.", predefinedOptions.name());
301: 
302:         // configurable options
303:         this.configurableOptions = mergeConfigurableOptions(original.configurableOptions, config);
304: 
305:         // configure RocksDB options factory
306:         try {
307:             rocksDbOptionsFactory =
308:                     configureOptionsFactory(
309:                             original.rocksDbOptionsFactory,
310:                             config.get(RocksDBOptions.OPTIONS_FACTORY),
311:                             config,
312:                             classLoader);
313:         } catch (DynamicCodeLoadingException e) {
314:             throw new FlinkRuntimeException(e);
315:         }
316: 
317:         // configure latency tracking
318:         latencyTrackingConfigBuilder = original.latencyTrackingConfigBuilder.configure(config);
319: 
320:         // configure overlap fraction threshold
321:         overlapFractionThreshold =
322:                 original.overlapFractionThreshold == UNDEFINED_OVERLAP_FRACTION_THRESHOLD
323:                         ? config.get(RESTORE_OVERLAP_FRACTION_THRESHOLD)
324:                         : original.overlapFractionThreshold;
325:         checkArgument(
326:                 overlapFractionThreshold >= 0 && this.overlapFractionThreshold <= 1,
327:                 "Overlap fraction threshold of restoring should be between 0 and 1");
328: 
329:         incrementalRestoreAsyncCompactAfterRescale =
330:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
331:                         original.incrementalRestoreAsyncCompactAfterRescale,
332:                         INCREMENTAL_RESTORE_ASYNC_COMPACT_AFTER_RESCALE,
333:                         config);
334: 
335:         useIngestDbRestoreMode =
336:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
337:                         original.useIngestDbRestoreMode, USE_INGEST_DB_RESTORE_MODE, config);
338: 
339:         rescalingUseDeleteFilesInRange =
340:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
341:                         original.rescalingUseDeleteFilesInRange,
342:                         USE_DELETE_FILES_IN_RANGE_DURING_RESCALING,
343:                         config);
344: 
345:         this.rocksDBMemoryFactory = original.rocksDBMemoryFactory;
346: 
347:         this.manualCompactionConfig =
348:                 original.manualCompactionConfig != null
349:                         ? original.manualCompactionConfig
350:                         : RocksDBManualCompactionConfig.from(config);
351:     }
