386:     private void lazyInitializeForJob(
387:             Environment env, @SuppressWarnings("unused") String operatorIdentifier)
388:             throws IOException {
389: 
390:         if (isInitialized) {
391:             return;
392:         }
393: 
394:         this.jobId = env.getJobID();
395: 
396:         // initialize the paths where the local RocksDB files should be stored
397:         if (localRocksDbDirectories == null) {
398:             initializedDbBasePaths = new File[] {env.getTaskManagerInfo().getTmpWorkingDirectory()};
399:         } else {
400:             List<File> dirs = new ArrayList<>(localRocksDbDirectories.length);
401:             StringBuilder errorMessage = new StringBuilder();
402: 
403:             for (File f : localRocksDbDirectories) {
404:                 File testDir = new File(f, UUID.randomUUID().toString());
405:                 if (!testDir.mkdirs()) {
406:                     String msg =
407:                             "Local DB files directory '"
408:                                     + f
409:                                     + "' does not exist and cannot be created. ";
410:                     LOG.error(msg);
411:                     errorMessage.append(msg);
412:                 } else {
413:                     dirs.add(f);
414:                 }
415:                 //noinspection ResultOfMethodCallIgnored
416:                 testDir.delete();
417:             }
418: 
419:             if (dirs.isEmpty()) {
420:                 throw new IOException("No local storage directories available. " + errorMessage);
421:             } else {
422:                 initializedDbBasePaths = dirs.toArray(new File[0]);
423:             }
424:         }
425: 
426:         nextDirectory = new Random().nextInt(initializedDbBasePaths.length);
427: 
428:         isInitialized = true;
429:     }
430: 
431:     private File getNextStoragePath() {
432:         int ni = nextDirectory + 1;
433:         ni = ni >= initializedDbBasePaths.length ? 0 : ni;
434:         nextDirectory = ni;
435: 
436:         return initializedDbBasePaths[ni];
437:     }
