443:     @Override
444:     public <K> AbstractKeyedStateBackend<K> createKeyedStateBackend(
445:             KeyedStateBackendParameters<K> parameters) throws IOException {
446:         Environment env = parameters.getEnv();
447: 
448:         // first, make sure that the RocksDB JNI library is loaded
449:         // we do this explicitly here to have better error handling
450:         String tempDir = env.getTaskManagerInfo().getTmpWorkingDirectory().getAbsolutePath();
451:         ensureRocksDBIsLoaded(tempDir);
452: 
453:         // replace all characters that are not legal for filenames with underscore
454:         String fileCompatibleIdentifier =
455:                 parameters.getOperatorIdentifier().replaceAll("[^a-zA-Z0-9\\-]", "_");
456: 
457:         lazyInitializeForJob(env, fileCompatibleIdentifier);
458: 
459:         File instanceBasePath =
460:                 new File(
461:                         getNextStoragePath(),
462:                         "job_"
463:                                 + jobId
464:                                 + "_op_"
465:                                 + fileCompatibleIdentifier
466:                                 + "_uuid_"
467:                                 + UUID.randomUUID());
468: 
469:         LocalRecoveryConfig localRecoveryConfig =
470:                 env.getTaskStateManager().createLocalRecoveryConfig();
471: 
472:         final OpaqueMemoryResource<RocksDBSharedResources> sharedResources =
473:                 RocksDBOperationUtils.allocateSharedCachesIfConfigured(
474:                         memoryConfiguration,
475:                         env,
476:                         parameters.getManagedMemoryFraction(),
477:                         LOG,
478:                         rocksDBMemoryFactory);
479:         if (sharedResources != null) {
480:             LOG.info("Obtained shared RocksDB cache of size {} bytes", sharedResources.getSize());
481:         }
482:         final RocksDBResourceContainer resourceContainer =
483:                 createOptionsAndResourceContainer(
484:                         sharedResources,
485:                         instanceBasePath,
486:                         nativeMetricOptions.isStatisticsEnabled());
487: 
488:         ExecutionConfig executionConfig = env.getExecutionConfig();
489:         StreamCompressionDecorator keyGroupCompressionDecorator =
490:                 getCompressionDecorator(executionConfig);
491: 
492:         LatencyTrackingStateConfig latencyTrackingStateConfig =
493:                 latencyTrackingConfigBuilder.setMetricGroup(parameters.getMetricGroup()).build();
494:         RocksDBKeyedStateBackendBuilder<K> builder =
495:                 new RocksDBKeyedStateBackendBuilder<>(
496:                                 parameters.getOperatorIdentifier(),
497:                                 env.getUserCodeClassLoader().asClassLoader(),
498:                                 instanceBasePath,
499:                                 resourceContainer,
500:                                 stateName -> resourceContainer.getColumnOptions(),
501:                                 parameters.getKvStateRegistry(),
502:                                 parameters.getKeySerializer(),
503:                                 parameters.getNumberOfKeyGroups(),
504:                                 parameters.getKeyGroupRange(),
505:                                 executionConfig,
506:                                 localRecoveryConfig,
507:                                 priorityQueueConfig,
508:                                 parameters.getTtlTimeProvider(),
509:                                 latencyTrackingStateConfig,
510:                                 parameters.getMetricGroup(),
511:                                 parameters.getCustomInitializationMetrics(),
512:                                 parameters.getStateHandles(),
513:                                 keyGroupCompressionDecorator,
514:                                 parameters.getCancelStreamRegistry())
515:                         .setEnableIncrementalCheckpointing(isIncrementalCheckpointsEnabled())
516:                         .setNumberOfTransferingThreads(getNumberOfTransferThreads())
517:                         .setNativeMetricOptions(
518:                                 resourceContainer.getMemoryWatcherOptions(nativeMetricOptions))
519:                         .setWriteBatchSize(getWriteBatchSize())
520:                         .setOverlapFractionThreshold(getOverlapFractionThreshold())
521:                         .setIncrementalRestoreAsyncCompactAfterRescale(
522:                                 getIncrementalRestoreAsyncCompactAfterRescale())
523:                         .setUseIngestDbRestoreMode(getUseIngestDbRestoreMode())
524:                         .setRescalingUseDeleteFilesInRange(isRescalingUseDeleteFilesInRange())
525:                         .setIOExecutor(
526:                                 MdcUtils.scopeToJob(
527:                                         jobId,
528:                                         parameters.getEnv().getIOManager().getExecutorService()))
529:                         .setManualCompactionConfig(
530:                                 manualCompactionConfig == null
531:                                         ? RocksDBManualCompactionConfig.getDefault()
532:                                         : manualCompactionConfig);
533:         return builder.build();
534:     }
