634:     /**
635:      * Sets the path where the RocksDB local database files should be stored on the local file
636:      * system. Setting this path overrides the default behavior, where the files are stored across
637:      * the configured temp directories.
638:      *
639:      * <p>Passing {@code null} to this function restores the default behavior, where the configured
640:      * temp directories will be used.
641:      *
642:      * @param path The path where the local RocksDB database files are stored.
643:      */
644:     public void setDbStoragePath(String path) {
645:         setDbStoragePaths(path == null ? null : new String[] {path});
646:     }
647: 
648:     /**
649:      * Sets the directories in which the local RocksDB database puts its files (like SST and
650:      * metadata files). These directories do not need to be persistent, they can be ephemeral,
651:      * meaning that they are lost on a machine failure, because state in RocksDB is persisted in
652:      * checkpoints.
653:      *
654:      * <p>If nothing is configured, these directories default to the TaskManager's local temporary
655:      * file directories.
656:      *
657:      * <p>Each distinct state will be stored in one path, but when the state backend creates
658:      * multiple states, they will store their files on different paths.
659:      *
660:      * <p>Passing {@code null} to this function restores the default behavior, where the configured
661:      * temp directories will be used.
662:      *
663:      * @param paths The paths across which the local RocksDB database files will be spread.
664:      */
665:     public void setDbStoragePaths(String... paths) {
666:         if (paths == null) {
667:             localRocksDbDirectories = null;
668:         } else if (paths.length == 0) {
669:             throw new IllegalArgumentException("empty paths");
670:         } else {
671:             File[] pp = new File[paths.length];
672: 
673:             for (int i = 0; i < paths.length; i++) {
674:                 final String rawPath = paths[i];
675:                 final String path;
676: 
677:                 if (rawPath == null) {
678:                     throw new IllegalArgumentException("null path");
679:                 } else {
680:                     // we need this for backwards compatibility, to allow URIs like 'file:///'...
681:                     URI uri = null;
682:                     try {
683:                         uri = new Path(rawPath).toUri();
684:                     } catch (Exception e) {
685:                         // cannot parse as a path
686:                     }
687: 
688:                     if (uri != null && uri.getScheme() != null) {
689:                         if ("file".equalsIgnoreCase(uri.getScheme())) {
690:                             path = uri.getPath();
691:                         } else {
692:                             throw new IllegalArgumentException(
693:                                     "Path " + rawPath + " has a non-local scheme");
694:                         }
695:                     } else {
696:                         path = rawPath;
697:                     }
698:                 }
699: 
700:                 pp[i] = new File(path);
701:                 if (!pp[i].isAbsolute()) {
702:                     throw new IllegalArgumentException("Relative paths are not supported");
703:                 }
704:             }
705: 
706:             localRocksDbDirectories = pp;
707:         }
708:     }
