313:     /**
314:      * Starts the mini cluster, based on the configured properties.
315:      *
316:      * @throws Exception This method passes on any exception that occurs during the startup of the
317:      *     mini cluster.
318:      */
319:     public void start() throws Exception {
320:         synchronized (lock) {
321:             checkState(!running, "MiniCluster is already running");
322: 
323:             LOG.info("Starting Flink Mini Cluster");
324:             LOG.debug("Using configuration {}", miniClusterConfiguration);
325: 
326:             final Configuration configuration = miniClusterConfiguration.getConfiguration();
327:             final boolean useSingleRpcService =
328:                     miniClusterConfiguration.getRpcServiceSharing() == RpcServiceSharing.SHARED;
329: 
330:             try {
331:                 workingDirectory =
332:                         WorkingDirectory.create(
333:                                 ClusterEntrypointUtils.generateWorkingDirectoryFile(
334:                                         configuration,
335:                                         Optional.of(PROCESS_WORKING_DIR_BASE),
336:                                         "minicluster_" + ResourceID.generate()));
337: 
338:                 initializeIOFormatClasses(configuration);
339: 
340:                 rpcSystem = rpcSystemSupplier.get();
341: 
342:                 LOG.info("Starting Metrics Registry");
343:                 metricRegistry =
344:                         createMetricRegistry(
345:                                 configuration,
346:                                 rpcSystem.deref().getMaximumMessageSizeInBytes(configuration));
347: 
348:                 // bring up all the RPC services
349:                 LOG.info("Starting RPC Service(s)");
350: 
351:                 final RpcServiceFactory dispatcherResourceManagerComponentRpcServiceFactory;
352:                 final RpcService metricQueryServiceRpcService;
353: 
354:                 if (useSingleRpcService) {
355:                     // we always need the 'commonRpcService' for auxiliary calls
356:                     commonRpcService = createLocalRpcService(configuration, rpcSystem.deref());
357:                     final CommonRpcServiceFactory commonRpcServiceFactory =
358:                             new CommonRpcServiceFactory(commonRpcService);
359:                     taskManagerRpcServiceFactory = commonRpcServiceFactory;
360:                     dispatcherResourceManagerComponentRpcServiceFactory = commonRpcServiceFactory;
361:                     metricQueryServiceRpcService =
362:                             MetricUtils.startLocalMetricsRpcService(
363:                                     configuration, rpcSystem.deref());
364:                 } else {
365: 
366:                     // start a new service per component, possibly with custom bind addresses
367:                     final String jobManagerExternalAddress =
368:                             miniClusterConfiguration.getJobManagerExternalAddress();
369:                     final String taskManagerExternalAddress =
370:                             miniClusterConfiguration.getTaskManagerExternalAddress();
371:                     final String jobManagerExternalPortRange =
372:                             miniClusterConfiguration.getJobManagerExternalPortRange();
373:                     final String taskManagerExternalPortRange =
374:                             miniClusterConfiguration.getTaskManagerExternalPortRange();
375:                     final String jobManagerBindAddress =
376:                             miniClusterConfiguration.getJobManagerBindAddress();
377:                     final String taskManagerBindAddress =
378:                             miniClusterConfiguration.getTaskManagerBindAddress();
379: 
380:                     dispatcherResourceManagerComponentRpcServiceFactory =
381:                             new DedicatedRpcServiceFactory(
382:                                     configuration,
383:                                     jobManagerExternalAddress,
384:                                     jobManagerExternalPortRange,
385:                                     jobManagerBindAddress,
386:                                     rpcSystem.deref());
387:                     taskManagerRpcServiceFactory =
388:                             new DedicatedRpcServiceFactory(
389:                                     configuration,
390:                                     taskManagerExternalAddress,
391:                                     taskManagerExternalPortRange,
392:                                     taskManagerBindAddress,
393:                                     rpcSystem.deref());
394: 
395:                     // we always need the 'commonRpcService' for auxiliary calls
396:                     // bind to the JobManager address with port 0
397:                     commonRpcService =
398:                             createRemoteRpcService(
399:                                     configuration, jobManagerBindAddress, 0, rpcSystem.deref());
400:                     metricQueryServiceRpcService =
401:                             MetricUtils.startRemoteMetricsRpcService(
402:                                     configuration,
403:                                     commonRpcService.getAddress(),
404:                                     null,
405:                                     rpcSystem.deref());
406:                 }
407: 
408:                 metricRegistry.startQueryService(metricQueryServiceRpcService, null);
409: 
410:                 processMetricGroup =
411:                         MetricUtils.instantiateProcessMetricGroup(
412:                                 metricRegistry,
413:                                 RpcUtils.getHostname(commonRpcService),
414:                                 ConfigurationUtils.getSystemResourceMetricsProbingInterval(
415:                                         configuration));
416: 
417:                 ioExecutor =
418:                         Executors.newFixedThreadPool(
419:                                 ClusterEntrypointUtils.getPoolSize(configuration),
420:                                 new ExecutorThreadFactory("mini-cluster-io"));
421: 
422:                 delegationTokenManager =
423:                         DefaultDelegationTokenManagerFactory.create(
424:                                 configuration,
425:                                 miniClusterConfiguration.getPluginManager(),
426:                                 commonRpcService.getScheduledExecutor(),
427:                                 ioExecutor);
428:                 // Obtaining delegation tokens and propagating them to the local JVM receivers in a
429:                 // one-time fashion is required because BlobServer may connect to external file
430:                 // systems
431:                 delegationTokenManager.obtainDelegationTokens();
432: 
433:                 delegationTokenReceiverRepository =
434:                         new DelegationTokenReceiverRepository(
435:                                 configuration, miniClusterConfiguration.getPluginManager());
436: 
437:                 haServicesFactory = createHighAvailabilityServicesFactory(configuration);
438: 
439:                 haServices = createHighAvailabilityServices(configuration, ioExecutor);
440: 
441:                 blobServer =
442:                         BlobUtils.createBlobServer(
443:                                 configuration,
444:                                 Reference.borrowed(workingDirectory.getBlobStorageDirectory()),
445:                                 haServices.createBlobStore());
446:                 blobServer.start();
447: 
448:                 heartbeatServices = HeartbeatServices.fromConfiguration(configuration);
449: 
450:                 blobCacheService =
451:                         BlobUtils.createBlobCacheService(
452:                                 configuration,
453:                                 Reference.borrowed(workingDirectory.getBlobStorageDirectory()),
454:                                 haServices.createBlobStore(),
455:                                 new InetSocketAddress(
456:                                         InetAddress.getLocalHost(), blobServer.getPort()));
457: 
458:                 startTaskManagers();
459: 
460:                 MetricQueryServiceRetriever metricQueryServiceRetriever =
461:                         new RpcMetricQueryServiceRetriever(
462:                                 metricRegistry.getMetricQueryServiceRpcService());
463: 
464:                 setupDispatcherResourceManagerComponents(
465:                         configuration,
466:                         dispatcherResourceManagerComponentRpcServiceFactory,
467:                         metricQueryServiceRetriever);
468: 
469:                 resourceManagerLeaderRetriever = haServices.getResourceManagerLeaderRetriever();
470:                 dispatcherLeaderRetriever = haServices.getDispatcherLeaderRetriever();
471:                 clusterRestEndpointLeaderRetrievalService =
472:                         haServices.getClusterRestEndpointLeaderRetriever();
473: 
474:                 dispatcherGatewayRetriever =
475:                         new RpcGatewayRetriever<>(
476:                                 commonRpcService,
477:                                 DispatcherGateway.class,
478:                                 DispatcherId::fromUuid,
479:                                 new ExponentialBackoffRetryStrategy(
480:                                         21, Duration.ofMillis(5L), Duration.ofMillis(20L)));
481:                 resourceManagerGatewayRetriever =
482:                         new RpcGatewayRetriever<>(
483:                                 commonRpcService,
484:                                 ResourceManagerGateway.class,
485:                                 ResourceManagerId::fromUuid,
486:                                 new ExponentialBackoffRetryStrategy(
487:                                         21, Duration.ofMillis(5L), Duration.ofMillis(20L)));
488:                 webMonitorLeaderRetriever = new LeaderRetriever();
489: 
490:                 resourceManagerLeaderRetriever.start(resourceManagerGatewayRetriever);
491:                 dispatcherLeaderRetriever.start(dispatcherGatewayRetriever);
492:                 clusterRestEndpointLeaderRetrievalService.start(webMonitorLeaderRetriever);
493:             } catch (Exception e) {
494:                 // cleanup everything
495:                 try {
496:                     close();
497:                 } catch (Exception ee) {
498:                     e.addSuppressed(ee);
499:                 }
500:                 throw e;
501:             }
502: 
503:             // create a new termination future
504:             terminationFuture = new CompletableFuture<>();
505: 
506:             // now officially mark this as running
507:             running = true;
508: 
509:             LOG.info("Flink Mini Cluster started successfully");
510:         }
511:     }
