583:     private HighAvailabilityServicesFactory createHighAvailabilityServicesFactory(
584:             Configuration configuration) {
585:         final HaServices customMiniClusterHaServicesMode = miniClusterConfiguration.getHaServices();
586:         if (customMiniClusterHaServicesMode == HaServices.WITH_LEADERSHIP_CONTROL) {
587:             // special feature of MiniClusters to allow the control of leadership
588:             // EmbeddedLeaderElection requires a single instance for leader election across multiple
589:             // JobManager instances on the same JVM (after FLINK-24038 was introduced); therefore,
590:             // SingletonHighAvailabilityServicesFactory is utilized here
591:             return new SingletonHighAvailabilityServicesFactory(
592:                     (config, embeddedLeaderElectionExecutor) ->
593:                             new EmbeddedHaServicesWithLeadershipControl(
594:                                     embeddedLeaderElectionExecutor));
595:         } else if (customMiniClusterHaServicesMode != HaServices.CONFIGURED) {
596:             throw new IllegalConfigurationException(
597:                     "Unknown HA Services Mode configured in MiniCluster configuration: "
598:                             + customMiniClusterHaServicesMode);
599:         }
600: 
601:         final RestoreMode highAvailabilityMode =
602:                 org.apache.flink.runtime.jobmanager.RestoreMode.fromConfig(configuration);
603:         if (highAvailabilityMode == RestoreMode.NONE) {
604:             // basic EmbeddedLeaderElection requires a single instance for leader election across
605:             // multiple JobManager instances on the same JVM (after FLINK-24038 was introduced);
606:             // therefore, SingletonHighAvailabilityServicesFactory is utilized here
607:             return new SingletonHighAvailabilityServicesFactory(
608:                     (config, embeddedLeaderElectionExecutor) ->
609:                             new EmbeddedHaServices(embeddedLeaderElectionExecutor));
610:         } else {
611:             return new RegularHighAvailabilityServicesFactory();
612:         }
613:     }
