642:     /**
643:      * Shuts down the mini cluster, failing all currently executing jobs. The mini cluster can be
644:      * started again by calling the {@link #start()} method again.
645:      *
646:      * <p>This method shuts down all started services and components, even if an exception occurs in
647:      * the process of shutting down some component.
648:      *
649:      * @return Future which is completed once the MiniCluster has been completely shut down
650:      */
651:     @Override
652:     public CompletableFuture<Void> closeAsync() {
653:         return closeInternal(true);
654:     }
655: 
656:     public CompletableFuture<Void> closeAsyncWithoutCleaningHighAvailabilityData() {
657:         return closeInternal(false);
658:     }
659: 
660:     private CompletableFuture<Void> closeInternal(boolean cleanupHaData) {
661:         synchronized (lock) {
662:             if (running) {
663:                 LOG.info("Shutting down Flink Mini Cluster");
664:                 try {
665:                     final long shutdownTimeoutMillis =
666:                             miniClusterConfiguration
667:                                     .getConfiguration()
668:                                     .get(ClusterOptions.CLUSTER_SERVICES_SHUTDOWN_TIMEOUT)
669:                                     .toMillis();
670:                     final int numComponents = 2 + miniClusterConfiguration.getNumTaskManagers();
671:                     final Collection<CompletableFuture<Void>> componentTerminationFutures =
672:                             new ArrayList<>(numComponents);
673: 
674:                     componentTerminationFutures.addAll(terminateTaskManagers());
675: 
676:                     componentTerminationFutures.add(shutDownResourceManagerComponents());
677: 
678:                     final FutureUtils.ConjunctFuture<Void> componentsTerminationFuture =
679:                             FutureUtils.completeAll(componentTerminationFutures);
680: 
681:                     final CompletableFuture<Void> metricSystemTerminationFuture =
682:                             FutureUtils.composeAfterwards(
683:                                     componentsTerminationFuture, this::closeMetricSystem);
684: 
685:                     final CompletableFuture<Void> rpcServicesTerminationFuture =
686:                             FutureUtils.composeAfterwards(
687:                                     metricSystemTerminationFuture, this::terminateRpcServices);
688: 
689:                     final CompletableFuture<Void> remainingServicesTerminationFuture =
690:                             FutureUtils.runAfterwards(
691:                                     rpcServicesTerminationFuture,
692:                                     () -> terminateMiniClusterServices(cleanupHaData));
693: 
694:                     final CompletableFuture<Void> executorsTerminationFuture =
695:                             FutureUtils.composeAfterwards(
696:                                     remainingServicesTerminationFuture,
697:                                     () -> terminateExecutors(shutdownTimeoutMillis));
698: 
699:                     final CompletableFuture<Void> deleteDirectoriesFuture =
700:                             FutureUtils.runAfterwards(
701:                                     executorsTerminationFuture, this::deleteDirectories);
702: 
703:                     deleteDirectoriesFuture.whenComplete(
704:                             (Void ignored, Throwable throwable) -> {
705:                                 if (throwable != null) {
706:                                     terminationFuture.completeExceptionally(
707:                                             ExceptionUtils.stripCompletionException(throwable));
708:                                 } else {
709:                                     terminationFuture.complete(null);
710:                                 }
711:                             });
712:                 } finally {
713:                     running = false;
714:                 }
715:             }
716: 
717:             return terminationFuture;
718:         }
719:     }
720: 
721:     private CompletableFuture<Void> closeMetricSystem() {
722:         synchronized (lock) {
723:             final ArrayList<CompletableFuture<Void>> terminationFutures = new ArrayList<>(2);
724: 
725:             if (processMetricGroup != null) {
726:                 processMetricGroup.close();
727:                 processMetricGroup = null;
728:             }
729: 
730:             // metrics shutdown
731:             if (metricRegistry != null) {
732:                 terminationFutures.add(metricRegistry.closeAsync());
733:                 metricRegistry = null;
734:             }
735: 
736:             return FutureUtils.completeAll(terminationFutures);
737:         }
738:     }
