604:             // basic EmbeddedLeaderElection requires a single instance for leader election across
605:             // multiple JobManager instances on the same JVM (after FLINK-24038 was introduced);
606:             // therefore, SingletonHighAvailabilityServicesFactory is utilized here
607:             return new SingletonHighAvailabilityServicesFactory(
608:                     (config, embeddedLeaderElectionExecutor) ->
609:                             new EmbeddedHaServices(embeddedLeaderElectionExecutor));
