1007:     /**
1008:      * This method executes a job in detached mode. The method returns immediately after the job has
1009:      * been added to the
1010:      *
1011:      * @param job The Flink job to execute
1012:      * @throws JobExecutionException Thrown if anything went amiss during initial job launch, or if
1013:      *     the job terminally failed.
1014:      */
1015:     public void runDetached(JobGraph job) throws JobExecutionException, InterruptedException {
1016:         checkNotNull(job, "job is null");
1017: 
1018:         final CompletableFuture<JobSubmissionResult> submissionFuture = submitJob(job);
1019: 
1020:         try {
1021:             submissionFuture.get();
1022:         } catch (ExecutionException e) {
1023:             throw new JobExecutionException(
1024:                     job.getJobID(), ExceptionUtils.stripExecutionException(e));
1025:         }
1026:     }
1027: 
1028:     /**
1029:      * This method runs a job in blocking mode. The method returns only after the job completed
1030:      * successfully, or after it failed terminally.
1031:      *
1032:      * @param job The Flink job to execute
1033:      * @return The result of the job execution
1034:      * @throws JobExecutionException Thrown if anything went amiss during initial job launch, or if
1035:      *     the job terminally failed.
1036:      */
1037:     public JobExecutionResult executeJobBlocking(JobGraph job)
1038:             throws JobExecutionException, InterruptedException {
1039:         checkNotNull(job, "job is null");
1040: 
1041:         final CompletableFuture<JobSubmissionResult> submissionFuture = submitJob(job);
1042: 
1043:         final CompletableFuture<JobResult> jobResultFuture =
1044:                 submissionFuture.thenCompose(
1045:                         (JobSubmissionResult ignored) -> requestJobResult(job.getJobID()));
1046: 
1047:         final JobResult jobResult;
1048: 
1049:         try {
1050:             jobResult = jobResultFuture.get();
1051:         } catch (ExecutionException e) {
1052:             throw new JobExecutionException(
1053:                     job.getJobID(),
1054:                     "Could not retrieve JobResult.",
1055:                     ExceptionUtils.stripExecutionException(e));
1056:         }
1057: 
1058:         try {
1059:             return jobResult.toJobExecutionResult(Thread.currentThread().getContextClassLoader());
1060:         } catch (IOException | ClassNotFoundException e) {
1061:             throw new JobExecutionException(job.getJobID(), e);
1062:         }
1063:     }
