1065:     public CompletableFuture<JobSubmissionResult> submitJob(JobGraph jobGraph) {
1066:         // When MiniCluster uses the local RPC, the provided JobGraph is passed directly to the
1067:         // Dispatcher. This means that any mutations to the JG can affect the Dispatcher behaviour,
1068:         // so we rather clone it to guard against this.
1069:         final JobGraph clonedJobGraph = InstantiationUtil.cloneUnchecked(jobGraph);
1070:         checkRestoreModeForChangelogStateBackend(clonedJobGraph);
1071:         final CompletableFuture<DispatcherGateway> dispatcherGatewayFuture =
1072:                 getDispatcherGatewayFuture();
1073:         final CompletableFuture<InetSocketAddress> blobServerAddressFuture =
1074:                 createBlobServerAddress(dispatcherGatewayFuture);
1075:         final CompletableFuture<Void> jarUploadFuture =
1076:                 uploadAndSetJobFiles(blobServerAddressFuture, clonedJobGraph);
1077:         final CompletableFuture<Acknowledge> acknowledgeCompletableFuture =
1078:                 jarUploadFuture
1079:                         .thenCombine(
1080:                                 dispatcherGatewayFuture,
1081:                                 (Void ack, DispatcherGateway dispatcherGateway) ->
1082:                                         dispatcherGateway.submitJob(clonedJobGraph, rpcTimeout))
1083:                         .thenCompose(Function.identity());
1084:         return acknowledgeCompletableFuture.thenApply(
1085:                 (Acknowledge ignored) -> new JobSubmissionResult(clonedJobGraph.getJobID()));
1086:     }
