1088:     // HACK: temporary hack to make the randomized changelog state backend tests work with forced
1089:     // full snapshots. This option should be removed once changelog state backend supports forced
1090:     // full snapshots
1091:     private void checkRestoreModeForChangelogStateBackend(JobGraph jobGraph) {
1092:         final SavepointRestoreSettings savepointRestoreSettings =
1093:                 jobGraph.getSavepointRestoreSettings();
1094:         if (overrideRestoreModeForChangelogStateBackend
1095:                 && savepointRestoreSettings.getRestoreMode() == org.apache.flink.core.execution.RecoveryClaimMode.NO_CLAIM) {
1096:             final Configuration conf = new Configuration();
1097:             SavepointRestoreSettings.toConfiguration(savepointRestoreSettings, conf);
1098:             conf.set(StateRecoveryOptions.CLAIM_MODE, org.apache.flink.core.execution.RecoveryClaimMode.LEGACY);
1099:             jobGraph.setSavepointRestoreSettings(SavepointRestoreSettings.fromConfiguration(conf));
1100:         }
1101:     }
