537:     private CompletableFuture<CompletedCheckpoint> triggerSavepointInternal(
538:             final CheckpointProperties checkpointProperties,
539:             @Nullable final String targetLocation) {
540: 
541:         checkNotNull(checkpointProperties);
542: 
543:         return triggerCheckpointFromCheckpointThread(checkpointProperties, targetLocation, false);
