546:     private CompletableFuture<CompletedCheckpoint> triggerCheckpointFromCheckpointThread(
547:             CheckpointProperties checkpointProperties, String targetLocation, boolean isPeriodic) {
548:         // TODO, call triggerCheckpoint directly after removing timer thread
549:         // for now, execute the trigger in timer thread to avoid competition
550:         final CompletableFuture<CompletedCheckpoint> resultFuture = new CompletableFuture<>();
551:         timer.execute(
552:                 () ->
553:                         triggerCheckpoint(checkpointProperties, targetLocation, isPeriodic)
554:                                 .whenComplete(
555:                                         (completedCheckpoint, throwable) -> {
556:                                             if (throwable == null) {
557:                                                 resultFuture.complete(completedCheckpoint);
558:                                             } else {
559:                                                 resultFuture.completeExceptionally(throwable);
560:                                             }
561:                                         }));
562:         return resultFuture;
563:     }
