630:     private void startTriggeringCheckpoint(CheckpointTriggerRequest request) {
631:         try {
632:             synchronized (lock) {
633:                 preCheckGlobalState(request.isPeriodic);
634:             }
635: 
636:             // we will actually trigger this checkpoint!
637:             Preconditions.checkState(!isTriggering);
638:             isTriggering = true;
639: 
640:             final long timestamp = System.currentTimeMillis();
641: 
642:             CompletableFuture<CheckpointPlan> checkpointPlanFuture =
643:                     checkpointPlanCalculator.calculateCheckpointPlan();
644: 
645:             boolean initializeBaseLocations = !baseLocationsForCheckpointInitialized;
646:             baseLocationsForCheckpointInitialized = true;
647: 
648:             CompletableFuture<Void> masterTriggerCompletionPromise = new CompletableFuture<>();
649: 
650:             final CompletableFuture<PendingCheckpoint> pendingCheckpointCompletableFuture =
651:                     checkpointPlanFuture
652:                             .thenApplyAsync(
653:                                     plan -> {
654:                                         try {
655:                                             // this must happen outside the coordinator-wide lock,
656:                                             // because it communicates with external services
657:                                             // (in HA mode) and may block for a while.
658:                                             long checkpointID =
659:                                                     checkpointIdCounter.getAndIncrement();
660:                                             return new Tuple2<>(plan, checkpointID);
661:                                         } catch (Throwable e) {
662:                                             throw new CompletionException(e);
663:                                         }
664:                                     },
665:                                     executor)
666:                             .thenApplyAsync(
667:                                     (checkpointInfo) ->
668:                                             createPendingCheckpoint(
669:                                                     timestamp,
670:                                                     request.props,
671:                                                     checkpointInfo.f0,
672:                                                     request.isPeriodic,
673:                                                     checkpointInfo.f1,
674:                                                     request.getOnCompletionFuture(),
675:                                                     masterTriggerCompletionPromise),
676:                                     timer);
677: 
678:             final CompletableFuture<?> coordinatorCheckpointsComplete =
679:                     pendingCheckpointCompletableFuture
680:                             .thenApplyAsync(
681:                                     pendingCheckpoint -> {
682:                                         try {
683:                                             CheckpointStorageLocation checkpointStorageLocation =
684:                                                     initializeCheckpointLocation(
685:                                                             pendingCheckpoint.getCheckpointID(),
686:                                                             request.props,
687:                                                             request.externalSavepointLocation,
688:                                                             initializeBaseLocations);
689:                                             return Tuple2.of(
690:                                                     pendingCheckpoint, checkpointStorageLocation);
691:                                         } catch (Throwable e) {
692:                                             throw new CompletionException(e);
693:                                         }
694:                                     },
695:                                     executor)
696:                             .thenComposeAsync(
697:                                     (checkpointInfo) -> {
698:                                         PendingCheckpoint pendingCheckpoint = checkpointInfo.f0;
699:                                         if (pendingCheckpoint.isDisposed()) {
700:                                             // The disposed checkpoint will be handled later,
701:                                             // skip snapshotting the coordinator states.
702:                                             return null;
703:                                         }
704:                                         synchronized (lock) {
705:                                             pendingCheckpoint.setCheckpointTargetLocation(
706:                                                     checkpointInfo.f1);
707:                                         }
708:                                         return OperatorCoordinatorCheckpoints
709:                                                 .triggerAndAcknowledgeAllCoordinatorCheckpointsWithCompletion(
710:                                                         coordinatorsToCheckpoint,
711:                                                         pendingCheckpoint,
712:                                                         timer);
713:                                     },
714:                                     timer);
715: 
716:             // We have to take the snapshot of the master hooks after the coordinator checkpoints
717:             // has completed.
718:             // This is to ensure the tasks are checkpointed after the OperatorCoordinators in case
719:             // ExternallyInducedSource is used.
720:             final CompletableFuture<?> masterStatesComplete =
721:                     coordinatorCheckpointsComplete.thenComposeAsync(
722:                             ignored -> {
723:                                 // If the code reaches here, the pending checkpoint is guaranteed to
724:                                 // be not null.
725:                                 // We use FutureUtils.getWithoutException() to make compiler happy
726:                                 // with checked
727:                                 // exceptions in the signature.
728:                                 PendingCheckpoint checkpoint =
729:                                         FutureUtils.getWithoutException(
730:                                                 pendingCheckpointCompletableFuture);
731:                                 if (checkpoint == null || checkpoint.isDisposed()) {
732:                                     // The disposed checkpoint will be handled later,
733:                                     // skip snapshotting the master states.
734:                                     return null;
735:                                 }
736:                                 return snapshotMasterState(checkpoint);
737:                             },
738:                             timer);
739: 
740:             FutureUtils.forward(
741:                     CompletableFuture.allOf(masterStatesComplete, coordinatorCheckpointsComplete),
742:                     masterTriggerCompletionPromise);
743: 
744:             FutureUtils.assertNoException(
745:                     masterTriggerCompletionPromise
746:                             .handleAsync(
747:                                     (ignored, throwable) -> {
748:                                         final PendingCheckpoint checkpoint =
749:                                                 FutureUtils.getWithoutException(
750:                                                         pendingCheckpointCompletableFuture);
751: 
752:                                         Preconditions.checkState(
753:                                                 checkpoint != null || throwable != null,
754:                                                 "Either the pending checkpoint needs to be created or an error must have occurred.");
755: 
756:                                         if (throwable != null) {
757:                                             // the initialization might not be finished yet
758:                                             if (checkpoint == null) {
759:                                                 onTriggerFailure(request, throwable);
760:                                             } else {
761:                                                 onTriggerFailure(checkpoint, throwable);
762:                                             }
763:                                         } else {
764:                                             triggerCheckpointRequest(
765:                                                     request, timestamp, checkpoint);
766:                                         }
767:                                         return null;
768:                                     },
769:                                     timer)
770:                             .exceptionally(
771:                                     error -> {
772:                                         if (!isShutdown()) {
773:                                             throw new CompletionException(error);
774:                                         } else if (findThrowable(
775:                                                         error, RejectedExecutionException.class)
776:                                                 .isPresent()) {
777:                                             LOG.debug("Execution rejected during shutdown");
778:                                         } else {
779:                                             LOG.warn("Error encountered during shutdown", error);
780:                                         }
781:                                         return null;
782:                                     }));
783:         } catch (Throwable throwable) {
784:             onTriggerFailure(request, throwable);
785:         }
786:     }
