2405:     private PendingCheckpointStats trackPendingCheckpointStats(
2406:             long checkpointId,
2407:             CheckpointPlan checkpointPlan,
2408:             CheckpointProperties props,
2409:             long checkpointTimestamp) {
2410:         Map<JobVertexID, Integer> vertices =
2411:                 Stream.concat(
2412:                                 checkpointPlan.getTasksToWaitFor().stream(),
2413:                                 checkpointPlan.getFinishedTasks().stream())
2414:                         .map(Execution::getVertex)
2415:                         .map(ExecutionVertex::getJobVertex)
2416:                         .distinct()
2417:                         .collect(
2418:                                 toMap(
2419:                                         ExecutionJobVertex::getJobVertexId,
2420:                                         ExecutionJobVertex::getParallelism));
2421: 
2422:         PendingCheckpointStats pendingCheckpointStats =
2423:                 statsTracker.reportPendingCheckpoint(
2424:                         checkpointId, checkpointTimestamp, props, vertices);
2425: 
2426:         reportFinishedTasks(pendingCheckpointStats, checkpointPlan.getFinishedTasks());
2427: 
2428:         return pendingCheckpointStats;
2429:     }
