2431:     private void reportFinishedTasks(
2432:             @Nullable PendingCheckpointStats pendingCheckpointStats,
2433:             List<Execution> finishedTasks) {
2434:         if (pendingCheckpointStats == null) {
2435:             return;
2436:         }
2437: 
2438:         long now = System.currentTimeMillis();
2439:         finishedTasks.forEach(
2440:                 execution ->
2441:                         pendingCheckpointStats.reportSubtaskStats(
2442:                                 execution.getVertex().getJobvertexId(),
2443:                                 new SubtaskStateStats(execution.getParallelSubtaskIndex(), now)));
2444:     }
