412:     public static FlinkPod loadPodFromTemplateFile(
413:             FlinkKubeClient kubeClient, File podTemplateFile, String mainContainerName) {
414:         final KubernetesPod pod = kubeClient.loadPodFromTemplateFile(podTemplateFile);
415:         final List<Container> otherContainers = new ArrayList<>();
416:         Container mainContainer = null;
417: 
418:         if (null != pod.getInternalResource().getSpec()) {
419:             for (Container container : pod.getInternalResource().getSpec().getContainers()) {
420:                 if (mainContainerName.equals(container.getName())) {
421:                     mainContainer = container;
422:                 } else {
423:                     otherContainers.add(container);
424:                 }
425:             }
426:             pod.getInternalResource().getSpec().setContainers(otherContainers);
427:         } else {
428:             // Set an empty spec for pod template
429:             pod.getInternalResource().setSpec(new PodSpecBuilder().build());
430:         }
431: 
432:         if (mainContainer == null) {
433:             LOG.info(
434:                     "Could not find main container {} in pod template, using empty one to initialize.",
435:                     mainContainerName);
436:             mainContainer = new ContainerBuilder().build();
437:         }
438: 
439:         return new FlinkPod(pod.getInternalResource(), mainContainer);
440:     }
