588:     public static String encodeLeaderInformation(LeaderInformation leaderInformation) {
589:         Preconditions.checkArgument(leaderInformation.getLeaderSessionID() != null);
590:         Preconditions.checkArgument(leaderInformation.getLeaderAddress() != null);
591: 
592:         return leaderInformation.getLeaderSessionID().toString()
593:                 + LEADER_INFORMATION_SEPARATOR
594:                 + leaderInformation.getLeaderAddress();
595:     }
