597:     public static Optional<LeaderInformation> parseLeaderInformationSafely(String value) {
598:         try {
599:             return Optional.of(parseLeaderInformation(value));
600:         } catch (Throwable throwable) {
601:             LOG.debug("Could not parse value {} into LeaderInformation.", value, throwable);
602:             return Optional.empty();
603:         }
604:     }
605: 
606:     private static LeaderInformation parseLeaderInformation(String value) {
607:         final int splitIndex = value.indexOf(LEADER_INFORMATION_SEPARATOR);
608: 
609:         Preconditions.checkState(
610:                 splitIndex >= 0,
611:                 String.format(
612:                         "Expecting '<session_id>%c<leader_address>'",
613:                         LEADER_INFORMATION_SEPARATOR));
614: 
615:         final UUID leaderSessionId = UUID.fromString(value.substring(0, splitIndex));
616:         final String leaderAddress = value.substring(splitIndex + 1);
617: 
618:         return LeaderInformation.known(leaderSessionId, leaderAddress);
619:     }
