447:     /**
448:      * Resolve the user defined value with the precedence. First an explicit config option value is
449:      * taken, then the value in pod template and at last the default value of a config option if
450:      * nothing is specified.
451:      *
452:      * @param flinkConfig flink configuration
453:      * @param configOption the config option to define the Kubernetes fields
454:      * @param valueOfConfigOptionOrDefault the value defined by explicit config option or default
455:      * @param valueOfPodTemplate the value defined in the pod template
456:      * @param fieldDescription Kubernetes fields description
457:      * @param <T> The type of value associated with the configuration option.
458:      * @return the resolved value
459:      */
460:     public static <T> String resolveUserDefinedValue(
461:             Configuration flinkConfig,
462:             ConfigOption<T> configOption,
463:             String valueOfConfigOptionOrDefault,
464:             @Nullable String valueOfPodTemplate,
465:             String fieldDescription) {
466:         final String resolvedValue;
467:         if (valueOfPodTemplate != null) {
468:             // The config option is explicitly set.
469:             if (flinkConfig.contains(configOption)) {
470:                 resolvedValue = valueOfConfigOptionOrDefault;
471:                 LOG.info(
472:                         "The {} configured in pod template will be overwritten to '{}' "
473:                                 + "because of explicitly configured options.",
474:                         fieldDescription,
475:                         resolvedValue);
476:             } else {
477:                 resolvedValue = valueOfPodTemplate;
478:             }
479:         } else {
480:             resolvedValue = valueOfConfigOptionOrDefault;
481:         }
482:         return resolvedValue;
483:     }
