89:             SharedStateRegistryFactory sharedStateRegistryFactory,
90:             ArrayDeque<CompletedCheckpoint> checkpoints,
91:             Executor ioExecutor,
92:             org.apache.flink.core.execution.RecoveryClaimMode restoreMode) {
93:         super(sharedStateRegistryFactory.create(ioExecutor, checkpoints, restoreMode));
94:         checkArgument(maxNumberOfCheckpointsToRetain >= 1, "Must retain at least one checkpoint.");
95:         this.maxNumberOfCheckpointsToRetain = maxNumberOfCheckpointsToRetain;
