102:     public CompletedCheckpoint addCheckpointAndSubsumeOldestOne(
103:             CompletedCheckpoint checkpoint,
104:             CheckpointsCleaner checkpointsCleaner,
105:             Runnable postCleanup)
106:             throws Exception {
107: 
108:         checkpoints.addLast(checkpoint);
109: 
110:         CompletedCheckpoint completedCheckpoint =
111:                 CheckpointSubsumeHelper.subsume(
112:                                 checkpoints,
113:                                 maxNumberOfCheckpointsToRetain,
114:                                 (cc) -> {
115:                                     cc.markAsDiscardedOnSubsume();
116:                                     checkpointsCleaner.addSubsumedCheckpoint(cc);
117:                                 })
118:                         .orElse(null);
119: 
120:         findLowest(checkpoints)
121:                 .ifPresent(
122:                         id ->
123:                                 checkpointsCleaner.cleanSubsumedCheckpoints(
124:                                         id,
125:                                         getSharedStateRegistry().unregisterUnusedState(id),
126:                                         postCleanup,
127:                                         ioExecutor));
128: 
129:         return completedCheckpoint;
