147:     @Override
148:     public void shutdown(JobStatus jobStatus, CheckpointsCleaner checkpointsCleaner)
149:             throws Exception {
150:         super.shutdown(jobStatus, checkpointsCleaner);
151:         try {
152:             LOG.info("Shutting down");
153: 
154:             long lowestRetained = Long.MAX_VALUE;
155:             for (CompletedCheckpoint checkpoint : checkpoints) {
156:                 if (checkpoint.shouldBeDiscardedOnShutdown(jobStatus)) {
157:                     checkpoint.markAsDiscardedOnShutdown(jobStatus).discard();
158:                 } else {
159:                     LOG.info(
160:                             "Checkpoint with ID {} at '{}' not discarded.",
161:                             checkpoint.getCheckpointID(),
162:                             checkpoint.getExternalPointer());
163:                     lowestRetained = Math.min(checkpoint.getCheckpointID(), lowestRetained);
164:                 }
165:             }
166:             if (jobStatus.isGloballyTerminalState()) {
167:                 // Now discard the shared state of not subsumed checkpoints - only if:
168:                 // - the job is in a globally terminal state. Otherwise,
169:                 // it can be a suspension, after which this state might still be needed.
170:                 // - checkpoint is not retained (it might be used externally)
171:                 // - checkpoint handle removal succeeded (e.g. from ZK) - otherwise, it might still
172:                 // be used in recovery if the job status is lost
173:                 checkpointsCleaner.cleanSubsumedCheckpoints(
174:                         lowestRetained,
175:                         getSharedStateRegistry().unregisterUnusedState(lowestRetained),
176:                         () -> {},
177:                         ioExecutor);
178:             }
179: 
180:         } finally {
181:             checkpoints.clear();
182:         }
183:     }
184: 
185:     @Override
