235:     public static Set<StateHandleID> getAllStateHandleId(JobID jobID, MiniCluster miniCluster)
236:             throws IOException, FlinkJobNotFoundException, ExecutionException,
237:                     InterruptedException {
238:         Optional<String> mostRecentCompletedCheckpointPath =
239:                 getLatestCompletedCheckpointPath(jobID, miniCluster);
240:         if (!mostRecentCompletedCheckpointPath.isPresent()) {
241:             return Collections.emptySet();
242:         }
243: 
244:         CheckpointMetadata checkpointMetadata;
245:         try {
246:             checkpointMetadata = loadCheckpointMetadata(mostRecentCompletedCheckpointPath.get());
247:         } catch (IOException ioException) {
248:             if (ExceptionUtils.findThrowable(ioException, FileNotFoundException.class)
249:                     .isPresent()) {
250:                 // return empty result when the metadata file do not exist due to subsumed
251:                 // checkpoint.
252:                 return Collections.emptySet();
253:             }
254:             throw ioException;
255:         }
256: 
257:         Set<StateHandleID> materializationIds =
258:                 checkpointMetadata.getOperatorStates().stream()
259:                         .flatMap(operatorState -> operatorState.getStates().stream())
260:                         .flatMap(
261:                                 operatorSubtaskState ->
262:                                         operatorSubtaskState.getManagedKeyedState().stream())
263:                         .flatMap(
264:                                 keyedStateHandle ->
265:                                         keyedStateHandle instanceof ChangelogStateBackendHandle
266:                                                 ? ((ChangelogStateBackendHandle) keyedStateHandle)
267:                                                         .getMaterializedStateHandles().stream()
268:                                                 : Stream.of(keyedStateHandle))
269:                         .map(KeyedStateHandle::getStateHandleId)
270:                         .collect(Collectors.toSet());
271:         if (!materializationIds.isEmpty()) {
272:             return materializationIds;
273:         }
274:         return Collections.emptySet();
275:     }
