295:     /** A source consumes data which is generated randomly and supports pre-handling record. */
296:     protected static class ControlledSource extends RichSourceFunction<Integer>
297:             implements CheckpointedFunction, CheckpointListener {
298: 
299:         private static final long serialVersionUID = 1L;
300: 
301:         protected volatile int currentIndex;
302: 
303:         protected final AtomicInteger completedCheckpointNum;
304: 
305:         protected volatile boolean isCanceled;
306: 
307:         private static final List<Integer> sourceList =
308:                 Collections.unmodifiableList(initSourceData(TOTAL_ELEMENTS));
309: 
310:         private transient ListState<Integer> currentIndexState;
311: 
312:         private transient ListState<Integer> completedCheckpointNumState;
313: 
314:         public ControlledSource() {
315:             this.completedCheckpointNum = new AtomicInteger();
316:         }
317: 
318:         public static List<Integer> initSourceData(int totalNum) {
319:             List<Integer> sourceList = new ArrayList<>(totalNum);
320:             for (int i = 0; i < totalNum; i++) {
321:                 sourceList.add(ThreadLocalRandom.current().nextInt(totalNum));
322:             }
323:             return sourceList;
324:         }
325: 
326:         public static Map<Integer, Integer> getExpectedResult() {
327:             return sourceList.stream()
328:                     .collect(
329:                             Collectors.toConcurrentMap(
330:                                     element -> element % 100, element -> 1, Integer::sum));
331:         }
332: 
333:         @Override
334:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
335:             currentIndexState.update(Collections.singletonList(currentIndex));
336:             completedCheckpointNumState.update(
337:                     Collections.singletonList(completedCheckpointNum.get()));
338:         }
339: 
340:         @Override
341:         public void initializeState(FunctionInitializationContext context) throws Exception {
342:             currentIndexState =
343:                     context.getOperatorStateStore()
344:                             .getListState(
345:                                     new ListStateDescriptor<>("currentIndexState", Integer.class));
346:             completedCheckpointNumState =
347:                     context.getOperatorStateStore()
348:                             .getListState(
349:                                     new ListStateDescriptor<>(
350:                                             "completedCheckpointNumState", Integer.class));
351:             if (context.isRestored()) {
352:                 currentIndex = get(currentIndexState.get(), 0);
353:                 completedCheckpointNum.compareAndSet(0, get(completedCheckpointNumState.get(), 0));
354:             }
355:         }
356: 
357:         @Override
358:         public void run(SourceContext<Integer> ctx) throws Exception {
359:             while (!isCanceled && currentIndex < sourceList.size()) {
360:                 beforeElement(ctx);
361:                 synchronized (ctx.getCheckpointLock()) {
362:                     if (!isCanceled && currentIndex < sourceList.size()) {
363:                         int currentElement = sourceList.get(currentIndex++);
364:                         ctx.collect(currentElement % 100);
365:                     }
366:                 }
367:             }
368:         }
369: 
370:         // it runs without holding the checkpoint lock
371:         protected void beforeElement(SourceContext<Integer> ctx) throws Exception {
372:             // do nothing by default
373:         }
374: 
375:         protected void waitWhile(SerializableBooleanSupplierWithException supplier)
376:                 throws Exception {
377:             while (supplier.getAsBoolean()) {
378:                 Thread.sleep(10);
379:             }
380:         }
381: 
382:         protected void throwArtificialFailure() throws Exception {
383:             throw new ArtificialFailure();
384:         }
385: 
386:         @Override
387:         public void cancel() {
388:             isCanceled = true;
389:         }
390: 
391:         @Override
392:         public void notifyCheckpointComplete(long checkpointId) throws Exception {
393:             completedCheckpointNum.getAndIncrement();
394:         }
395:     }
