398:     protected static class CollectionSink implements SinkFunction<Tuple2<Integer, Integer>> {
399: 
400:         private static final long serialVersionUID = 1L;
401: 
402:         private static final Map<Integer, Integer> expectedResult = new HashMap<>();
403: 
404:         @Override
405:         public void invoke(Tuple2<Integer, Integer> value, Context context) throws Exception {
406:             expectedResult.merge(value.f0, value.f1, Math::max);
407:         }
408: 
409:         public static void clearExpectedResult() {
410:             expectedResult.clear();
411:         }
412: 
413:         public static Map<Integer, Integer> getActualResult() {
414:             return expectedResult;
415:         }
416:     }
