418:     /** A Process function with value state mocks word count. */
419:     protected static class CountFunction
420:             extends KeyedProcessFunction<Integer, Integer, Tuple2<Integer, Integer>> {
421: 
422:         private static final long serialVersionUID = 1L;
423: 
424:         private ValueState<Integer> countState;
425: 
426:         @Override
427:         public void open(OpenContext openContext) throws Exception {
428:             this.countState =
429:                     getRuntimeContext()
430:                             .getState(new ValueStateDescriptor<>("countState", Integer.class));
431:         }
432: 
433:         @Override
434:         public void processElement(
435:                 Integer value, Context ctx, Collector<Tuple2<Integer, Integer>> out)
436:                 throws Exception {
437:             Integer count = countState.value();
438:             Integer currentCount = count == null ? 1 : count + 1;
439:             countState.update(currentCount);
440:             out.collect(Tuple2.of(value, currentCount));
441:         }
442:     }
