290:     private void verifyCheckpointExistOrWaitDeleted(
291:             String checkpointPath,
292:             TernaryBoolean exist,
293:             boolean fileMergingEnabled,
294:             CheckpointMetadata metadata)
295:             throws Exception {
296:         org.apache.flink.core.fs.Path checkpointDir =
297:                 new org.apache.flink.core.fs.Path(checkpointPath);
298:         FileSystem fs = checkpointDir.getFileSystem();
299:         org.apache.flink.core.fs.Path baseDir = checkpointDir.getParent();
300:         org.apache.flink.core.fs.Path sharedFile =
301:                 new org.apache.flink.core.fs.Path(baseDir, CHECKPOINT_SHARED_STATE_DIR);
302:         org.apache.flink.core.fs.Path taskOwnedFile =
303:                 new org.apache.flink.core.fs.Path(baseDir, CHECKPOINT_TASK_OWNED_STATE_DIR);
304:         assertThat(fs.exists(baseDir)).isTrue();
305:         assertThat(fs.exists(sharedFile)).isTrue();
306:         assertThat(fs.exists(taskOwnedFile)).isTrue();
307:         if (exist.equals(TernaryBoolean.TRUE)) {
308:             // should exist, just check
309:             assertThat(fs.exists(checkpointDir)).isTrue();
310:             assertThat(metadata == null || verifyCheckpointExist(metadata, true)).isTrue();
311:             // Since there is no exclusive state, we should consider fileMergingEnabled.
312:             assertThat(
313:                             fs.listStatus(taskOwnedFile) != null
314:                                     && fs.listStatus(taskOwnedFile).length > 0)
315:                     .isEqualTo(fileMergingEnabled);
316:         } else if (exist.equals(TernaryBoolean.FALSE)) {
317:             // should be cleaned, since the job io threads may work slow, we wait.
318:             long waited = 0L;
319:             boolean fileExist = true;
320:             while (fileExist) {
321:                 try {
322:                     fileExist =
323:                             (fs.exists(checkpointDir)
324:                                     || (metadata != null && !verifyCheckpointExist(metadata, false))
325:                                     || !verifyCheckpointNoDirectory(fs, sharedFile, taskOwnedFile));
326:                 } catch (IOException e) {
327:                     // Sometimes it may happen that the files are being deleted while we list them,
328:                     // thus an IOException is raised.
329:                 }
330:                 if (fileExist) {
331:                     // We wait
332:                     Thread.sleep(500L);
333:                     waited += 500L;
334:                     // Or timeout
335:                     if (waited >= DELETE_TIMEOUT_MILLS) {
336:                         assertThat(fs.exists(checkpointDir)).isFalse();
337:                         assertThat(fs.listStatus(sharedFile)).isNullOrEmpty();
338:                         assertThat(fs.listStatus(taskOwnedFile)).isNullOrEmpty();
339:                     }
340:                 }
341:             }
342:         }
343:     }
344: 
345:     /**
346:      * Traverse the checkpoint metadata and verify all the state handle exist or be disposed.
347:      *
348:      * @param metadata the metadata to traverse.
349:      * @param exist all corresponding files of the state handle should exist
350:      * @return true if all corresponding files are deleted.
351:      */
352:     private boolean verifyCheckpointExist(CheckpointMetadata metadata, boolean exist) {
353:         AtomicBoolean result = new AtomicBoolean(true);
354:         for (OperatorState operatorState : metadata.getOperatorStates()) {
355:             for (OperatorSubtaskState subtaskState : operatorState.getStates()) {
356:                 // Check keyed state handle
357:                 List<KeyedStateHandle> keyedStateHandles =
358:                         new ArrayList<>(subtaskState.getManagedKeyedState());
359:                 for (KeyedStateHandle keyedStateHandle : keyedStateHandles) {
360:                     assertThat(keyedStateHandle)
361:                             .isInstanceOf(IncrementalRemoteKeyedStateHandle.class);
362:                     boolean singleResult =
363:                             ((IncrementalRemoteKeyedStateHandle) keyedStateHandle)
364:                                     .streamSubHandles()
365:                                     .allMatch(
366:                                             handle -> {
367:                                                 try {
368:                                                     if (handle instanceof FileStateHandle) {
369:                                                         org.apache.flink.core.fs.Path p =
370:                                                                 ((FileStateHandle) handle)
371:                                                                         .getFilePath();
372:                                                         return exist == p.getFileSystem().exists(p);
373:                                                     } else if (handle
374:                                                             instanceof SegmentFileStateHandle) {
375:                                                         org.apache.flink.core.fs.Path p =
376:                                                                 ((SegmentFileStateHandle) handle)
377:                                                                         .getFilePath();
378:                                                         return exist == p.getFileSystem().exists(p);
379:                                                     }
380:                                                 } catch (IOException e) {
381:                                                     log.warn(
382:                                                             "An error occurred when trying to check the file existence.",
383:                                                             e);
384:                                                     return false;
385:                                                 }
386:                                                 return true;
387:                                             });
388:                     result.set(result.get() || singleResult);
389:                     if (!result.get()) {
390:                         break;
391:                     }
392:                 }
393:                 if (!result.get()) {
394:                     break;
395:                 }
396:                 List<OperatorStateHandle> operatorStateHandles =
397:                         new ArrayList<>(subtaskState.getManagedOperatorState());
398:                 for (OperatorStateHandle handle : operatorStateHandles) {
399:                     if (handle instanceof FileMergingOperatorStreamStateHandle) {
400:                         try {
401:                             org.apache.flink.core.fs.Path p =
402:                                     ((FileMergingOperatorStreamStateHandle) handle)
403:                                             .getSharedDirHandle()
404:                                             .getDirectory();
405:                             if (exist != p.getFileSystem().exists(p)) {
406:                                 result.set(false);
407:                             }
408:                             p =
409:                                     ((FileMergingOperatorStreamStateHandle) handle)
410:                                             .getTaskOwnedDirHandle()
411:                                             .getDirectory();
412:                             if (exist != p.getFileSystem().exists(p)) {
413:                                 result.set(false);
414:                             }
415:                         } catch (IOException e) {
416:                             log.warn(
417:                                     "An error occurred when trying to check the file existence.",
418:                                     e);
419:                             result.set(false);
420:                         }
421:                     }
422:                 }
423:                 if (!result.get()) {
424:                     break;
425:                 }
426:             }
427:         }
428:         return result.get();
429:     }
430: 
431:     /** Verifying that there is no subdirectory under shared and task-owned directory. */
432:     private static boolean verifyCheckpointNoDirectory(
433:             FileSystem fs,
434:             org.apache.flink.core.fs.Path sharedFile,
435:             org.apache.flink.core.fs.Path taskOwnedFile)
436:             throws IOException {
437:         FileStatus[] fileStatuses = fs.listStatus(sharedFile);
438:         if (fileStatuses != null) {
439:             for (FileStatus fileStatus : fileStatuses) {
440:                 if (fileStatus.isDir()) {
441:                     return false;
442:                 }
443:             }
444:         }
445:         fileStatuses = fs.listStatus(taskOwnedFile);
446:         if (fileStatuses != null) {
447:             for (FileStatus fileStatus : fileStatuses) {
448:                 if (fileStatus.isDir()) {
449:                     return false;
450:                 }
451:             }
452:         }
453:         return true;
454:     }
455: }
